<?php declare(strict_types=1); namespace App\Domains\Patient\Requests; use Illuminate\Foundation\Http\FormRequest;
final class UpdatePatientRequest extends FormRequest { public function authorize(): bool { return true; } public function rules(): array { return ['patient_code'=>'sometimes|string|max:30','full_name'=>'sometimes|string|max:200','birth_date'=>'nullable|date|before:today','gender'=>'nullable|string|max:10','blood_type'=>'nullable|string|max:5','religion'=>'nullable|string|max:20','marital_status'=>'nullable|string|max:20','nationality_id'=>'nullable|uuid|exists:nationalities,id','patient_type_id'=>'nullable|uuid|exists:patient_types,id','branch_id'=>'nullable|uuid|exists:branches,id','phone'=>'nullable|string|max:20','email'=>'nullable|email|max:100','address'=>'nullable|string','district_id'=>'nullable|uuid|exists:districts,id','village_id'=>'nullable|uuid|exists:villages,id']; } }
